#!/usr/bin/env python3
"""Extract pinned AMD 64-phase coefficient tables and selectors verbatim."""
import argparse
import hashlib
import re
from extract_scaler_geometry import ROOT, REF, COMMIT, extract

OUT = ROOT / 'driver/shim/generated/dc_scaler_filters.inc'


def generate():
    raw = (REF / 'dce_scl_filters.c').read_bytes()
    text = raw.decode('utf-8')
    pieces = ['/* SPDX-License-Identifier: MIT */',
              '/* Generated by tools/import/extract_scaler_filters.py. Do not edit.\n'
              f' * PROVENANCE: Linux amdgpu DC, MIT, {COMMIT}.\n'
              f' * dce_scl_filters.c SHA256 {hashlib.sha256(raw).hexdigest()} */',
              text[:text.index('*/') + 2]]
    # Only fraction conversion is needed by the upstream selection thresholds.
    fixed_raw = (REF / 'fixpt31_32.c').read_bytes()
    fixed = fixed_raw.decode('utf-8')
    pieces += [fixed[:fixed.index('*/') + 2],
               f'/* fixpt31_32.c SHA256 {hashlib.sha256(fixed_raw).hexdigest()} */',
               'static struct fixed31_32 dc_fixpt_from_fraction(long long, long long);',
               extract(fixed, 'complete_integer_division_u64'),
               extract(fixed, 'dc_fixpt_from_fraction')]
    names = ['filter_2tap_64p'] + [f'filter_{t}tap_64p_{suffix}'
              for t in range(3, 9) for suffix in ('upscale', '116', '149', '183')]
    for name in names:
        found = re.findall(r'^static const uint16_t ' + name +
                           r'\[\d+\] = \{.*?^\};', text, re.M | re.S)
        if len(found) != 1:
            raise ValueError(f'Expected one {name}')
        pieces.append(found[0])
    for taps in range(2, 9):
        name = f'get_filter_{taps}tap_64p'
        signature = 'void' if taps == 2 else 'struct fixed31_32 ratio'
        pieces.append(f'static const uint16_t *{name}({signature});')
        found = re.findall(r'^const uint16_t \*' + name +
                           r'\([^;]*?^\{\n.*?^\}', text, re.M | re.S)
        if len(found) != 1:
            raise ValueError(f'Expected one {name}')
        pieces.append(found[0])
    return ('\n\n'.join(pieces).rstrip() + '\n').encode('utf-8')


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    data = generate()
    if args.check:
        if OUT.read_bytes() != data:
            raise SystemExit('Scaler filter extraction is stale')
    else:
        OUT.write_bytes(data)
    print('Scaler filter extraction OK')


if __name__ == '__main__':
    main()
